VALUES (
  'Kalshi',
  'Get Kalshi Markets',
  'Get Kalshi Markets',
  '{"model":"claude-sonnet-4-20250514","systemPrompt":"You are a premium AI agent powered by Kalshi.\nPrediction market orderbooks from Kalshi\n\nYou have access to the following paid API tools (use the tool names exactly as shown):- kalshi__apis_v2_kalshi_markets: Get Kalshi Markets ($0.0200/call, GET)\n- kalshi__apis_v2_kalshi_trades: Get Kalshi Trades ($0.0200/call, GET)\n\nEach API call deducts from the user''s subscription usage budget. Use calls wisely and always explain what you''re doing before making them.\n\nAPI docs: https://aisa.one/docs/api-reference","isPremium":true,"circleServices":[{"name":"kalshi","endpoint":"https://api.aisa.one/apis/v2/kalshi/markets","pricePerCall":0.02,"description":"Get Kalshi Markets","method":"GET","tools":[{"name":"apis_v2_kalshi_markets","description":"Get Kalshi Markets","inputSchema":{"type":"object","properties":{"limit":{"type":"integer","default":10,"example":20,"maximum":100,"minimum":1,"description":"Number of markets to return (1-100). Default: 10."},"search":{"type":"string","example":"bitcoin","description":"Search markets by keywords in title and description. Must be URL encoded (e.g., ''bitcoin%20price'' for ''bitcoin price'')."},"status":{"enum":["open","closed"],"type":"string","example":"open","description":"Filter markets by status (whether they''re open or closed)"},"min_volume":{"type":"number","example":10000000,"description":"Filter markets with total trading volume greater than or equal to this amount (in dollars)"},"event_ticker":{"type":"array","items":{"type":"string"},"example":["KXMAYORNYCPARTY-25"],"description":"Filter markets by event ticker(s). Can provide multiple values."},"market_ticker":{"type":"array","items":{"type":"string"},"example":["KXMAYORNYCPARTY-25-D"],"description":"Filter markets by market ticker(s). Can provide multiple values."},"pagination_key":{"type":"string","example":"eyJvcGVuX3RpbWUiOiIyMDI1LTAxLTE5VDEyOjAwOjAwLjAwMFoiLCJtYXJrZXRfdGlja2VyIjoiS1hNQVlPUk5ZQ1BBUlRZLTI1LUQiLCJ0b3RhbCI6MTUwfQ==","description":"Base64-encoded cursor for efficient pagination. Returned in the previous response''s pagination object."}},"required":[]}}]},{"name":"kalshi","endpoint":"https://api.aisa.one/apis/v2/kalshi/trades","pricePerCall":0.02,"description":"Get Kalshi Trades","method":"GET","tools":[{"name":"apis_v2_kalshi_trades","description":"Get Kalshi Trades","inputSchema":{"type":"object","properties":{"limit":{"type":"integer","default":100,"example":10,"description":"Maximum number of trades to return (default: 100)"},"ticker":{"type":"string","example":"KXNFLGAME-25NOV09PITLAC-PIT","description":"The Kalshi market ticker to filter trades"},"end_time":{"type":"integer","example":1762720600,"description":"End time in Unix timestamp (seconds)"},"start_time":{"type":"integer","example":1762716000,"description":"Start time in Unix timestamp (seconds)"},"pagination_key":{"type":"string","example":"eyJjcmVhdGVkX3RpbWUiOiIyMDI1LTAxLTE5VDEyOjAwOjAwLjAwMFoiLCJ0cmFkZV9pZCI6IjEyMzQ1Njc4OTAiLCJ0b3RhbCI6NTAwMDB9","description":"Base64-encoded cursor for efficient pagination. Returned in the previous response''s pagination object."}},"required":[]}}]}],"appearance":{"skin":0,"hairStyle":2,"hair":0,"shirt":1,"pants":0,"accessory":1,"accent":1,"beard":0,"eyeColor":0,"headFeature":0}}',
