-- Agent 6: Polymarket (27 endpoint(s))
INSERT INTO heights_cloud_agents (name, description, summary, agent, language, use_cases, tags, is_free, price, price_usd, is_premium, category, requirements, links, image_url, status, created_at)
VALUES (
  'Polymarket',
  'Get Activity',
  'Get Activity',
  '{"model":"claude-sonnet-4-20250514","systemPrompt":"You are a premium AI agent powered by Polymarket.\nPrediction market odds and trades from Polymarket\n\nYou have access to the following paid API tools (use the tool names exactly as shown):- polymarket__apis_v2_polymarket_activity: Get Activity ($0.0120/call, GET)\n- polymarket__apis_v2_polymarket_events: Get Events ($0.0004/call, GET)\n- polymarket__apis_v2_polymarket_markets: Get Markets ($0.0004/call, GET)\n- polymarket__apis_v2_polymarket_orders: Get Orders ($0.0120/call, GET)\n- polymarket__api_v1_pm_binance_candles_BTCUSDT: Get OHLCV candlestick data for a Binance trading pair ($0.0050/call, GET)\n- polymarket__api_v1_pm_binance_ticks_ETHUSDT: Get raw book ticker data at microsecond granularity ($0.0050/call, GET)\n- polymarket__api_v1_pm_dflow_trades: Fetch trade history for a wallet on dFlow ($0.0010/call, GET)\n- polymarket__api_v1_pm_kalshi_markets: Query Kalshi markets with filtering, sorting, and pagination ($0.0010/call, GET)\n- polymarket__api_v1_pm_kalshi_orderbooks: Fetch historical orderbook snapshots for a Kalshi market ($0.0010/call, GET)\n- polymarket__api_v1_pm_kalshi_trades: Fetch historical Kalshi trade data ($0.0010/call, GET)\n- polymarket__api_v1_pm_matching_markets: Find equivalent markets across Polymarket and Kalshi ($0.0050/call, GET)\n- polymarket__api_v1_pm_matching_markets_pairs: Get all active exact-matched market pairs ($0.0050/call, GET)\n- polymarket__api_v1_pm_polymarket_activity: Fetch trading activity (merges, splits, redeems) for a user ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_candlesticks_hash: Get historical OHLCV candlestick data for a market ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_cohorts_stats: Compare performance across trading style cohorts ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_crypto_updown: List crypto up/down prediction markets ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_events: List Polymarket events with filtering and sorting ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_leaderboard: Get the global leaderboard of smart wallets ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_market_hash_smart_m: View smart money positioning on a specific market ($0.0050/call, GET)\n- polymarket__api_v1_pm_polymarket_market_hash_top_hol: Get top holders for a specific market ranked by position size ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_markets: Query Polymarket markets with filtering, sorting, and pagination ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_markets_smart_activ: Discover markets where high-performing wallets are active ($0.0050/call, GET)\n- polymarket__api_v1_pm_polymarket_orderbooks: Get historical orderbook snapshots for a token ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_positions: Fetch all user positions with filtering and pagination ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_trades: Query historical Polymarket trade data with flexible filtering ($0.0010/call, GET)\n- polymarket__api_v1_pm_polymarket_wallet_address: Get a complete smart wallet profile with all metrics ($0.0050/call, GET)\n- polymarket__api_v1_pm_polymarket_wallet_positions_ad: Get open and historical positions for a wallet address ($0.0050/call, GET)\n\nEach API call deducts from the user''s subscription usage budget. Use calls wisely and always explain what you''re doing before making them.\n\nAPI docs: https://aisa.one/docs/api-reference","isPremium":true,"circleServices":[{"name":"polymarket","endpoint":"https://api.aisa.one/apis/v2/polymarket/activity","pricePerCall":0.012,"description":"Get Activity","method":"GET","tools":[{"name":"apis_v2_polymarket_activity","description":"Get Activity","inputSchema":{"type":"object","properties":{"user":{"type":"string","example":"0x7c3db723f1d4d8cb9c550095203b686cb11e5c6b","pattern":"^0x[0-9a-fA-F]{40}$","description":"User wallet address to fetch activity for. If not provided, returns activity for all users."},"limit":{"type":"integer","default":100,"example":50,"maximum":1000,"minimum":1,"description":"Number of activities to return (1-1000)"},"end_time":{"type":"integer","example":1672531200,"description":"Filter activity until this Unix timestamp in seconds (inclusive)"},"start_time":{"type":"integer","example":1640995200,"description":"Filter activity from this Unix timestamp in seconds (inclusive)"},"market_slug":{"type":"string","example":"bitcoin-up-or-down-july-25-8pm-et","description":"Filter activity by market slug"},"condition_id":{"type":"string","example":"0x4567b275e6b667a6217f5cb4f06a797d3a1eaf1d0281fb5bc8c75e2046ae7e57","description":"Filter activity by condition ID"},"pagination_key":{"type":"string","example":"eyJibG9ja190aW1lc3RhbXAiOiIyMDI1LTAxLTE5VDEyOjAwOjAwLjAwMFoiLCJzaWRlIjoiU1BMSVQiLCJ0eF9oYXNoIjoiMHgxMjM0NTY3ODkwYWJjZGVmIiwibG9nX2luZGV4IjoxMCwidG90YWwiOjE5ODkwMTc3Nn0=","description":"Base64-encoded cursor for efficient pagination. Returned in the previous response''s pagination object."}},"required":[]}}]},{"name":"polymarket","endpoint":"https://api.aisa.one/apis/v2/polymarket/events","pricePerCall":0.00044,"description":"Get Events","method":"GET","tools":[{"name":"apis_v2_polymarket_events","description":"Get Events","inputSchema":{"type":"object","properties":{"tags":{"type":"array","items":{"type":"string"},"example":["sports","football"],"description":"Filter events by tag(s)/category. Can provide multiple values (e.g., sports, crypto, politics)."},"limit":{"type":"integer","default":10,"example":10,"maximum":100,"minimum":1,"description":"Number of events to return (1-100). Default: 10."},"status":{"enum":["open","closed"],"type":"string","example":"open","description":"Filter events by status. An event is ''open'' if any of its markets are still open, ''closed'' if all markets are closed."},"end_time":{"type":"integer","example":1672531200,"description":"Filter events starting before this Unix timestamp (seconds)"},"event_slug":{"type":"string","example":"presidential-election-winner-2024","description":"Filter by specific event slug. When provided, returns a single hydrated event matching that slug (e.g., ''presidential-election-winner-2024''). Use with include_markets=true to get the full event with all its markets."},"start_time":{"type":"integer","example":1640995200,"description":"Filter events starting after this Unix timestamp (seconds)"},"pagination_key":{"type":"string","example":"eyJsYXN0Vm9sdW1lIjoxNzEyMTMyNjYzLjk2MTYwNjMsImxhc3RFdmVudFNsdWciOiJuYmEtY2hhbXBpb24tMjAyNC0yMDI1In0=","description":"Pagination key for cursor-based pagination. Use the value from the previous response''s pagination.pagination_key field to get the next page of results. Do not use the deprecated ''offset'' parameter."},"game_start_time":{"type":"integer","example":1704067200,"description":"Filter events by game start time (Unix timestamp in seconds). Useful for filtering sports events by when the game starts."},"include_markets":{"enum":["true","false"],"type":"string","default":"false","example":"true","description":"Set to ''true'' to include the list of markets for each event in the response."}},"required":[]}}]},{"name":"polymarket","endpoint":"https://api.aisa.one/apis/v2/polymarket/markets","pricePerCall":0.00044,"description":"Get Markets","method":"GET","tools":[{"name":"apis_v2_polymarket_markets","description":"Get Markets","inputSchema":{"type":"object","properties":{"tags":{"type":"array","items":{"type":"string"},"example":["politics","crypto"],"description":"Filter markets by tag(s). Can provide multiple values."},"limit":{"type":"integer","default":10,"example":20,"maximum":100,"minimum":1,"description":"Number of markets to return (1-100). Default: 10 for search, 10 for regular queries."},"search":{"type":"string","example":"bitcoin","description":"Search markets by keywords in title and description. Must be URL encoded (e.g., ''bitcoin%20price'' for ''bitcoin price'')."},"status":{"enum":["open","closed"],"type":"string","example":"open","description":"Filter markets by status (whether they''re open or closed)"},"end_time":{"type":"integer","example":1672531200,"description":"Filter markets until this Unix timestamp in seconds (inclusive)"},"token_id":{"type":"array","items":{"type":"string","pattern":"^[0-9]+$"},"example":["24891147099018724959141647991382271578149113344000019968758330059825991230807"],"maxItems":100,"description":"Filter markets by token ID(s). Matches markets where the token_id is either the primary_token_id or secondary_token_id. Can provide multiple values (maximum 100). Each token_id must be a numeric string."},"event_slug":{"type":"array","items":{"type":"string"},"example":["presidential-election-winner-2028"],"description":"Filter markets by event slug(s). Can provide multiple values."},"min_volume":{"type":"number","example":100000,"description":"Filter markets with total trading volume greater than or equal to this amount (USD)"},"start_time":{"type":"integer","example":1640995200,"description":"Filter markets from this Unix timestamp in seconds (inclusive)"},"market_slug":{"type":"array","items":{"type":"string"},"example":["bitcoin-up-or-down-july-25-8pm-et"],"description":"Filter markets by market slug(s). Can provide multiple values."},"condition_id":{"type":"array","items":{"type":"string"},"example":["0x4567b275e6b667a6217f5cb4f06a797d3a1eaf1d0281fb5bc8c75e2046ae7e57"],"description":"Filter markets by condition ID(s). Can provide multiple values."},"pagination_key":{"type":"string","example":"eyJzdGFydF9kYXRlIjoiMjAyNi0wMS0xOVQxMjowMDowMC4wMDBaIiwiY29uZGl0aW9uX2lkIjoiMHgxMjM0In0=","description":"Base64-encoded cursor for efficient pagination. Returned in the previous response''s pagination object. Use this instead of large offsets for better performance."}},"required":[]}}]},{"name":"polymarket","endpoint":"https://api.aisa.one/apis/v2/polymarket/orders","pricePerCall":0.012,"description":"Get O